namespace ghidra.graph.viewer.layout;



/**
 * Row and column information for points in a {@link GridLocationMap}. Using these instead
 * of java Points, makes the code that translates from grid space to layout space much less
 * confusing.
 */
public class GridPoint {

	public int row;
	public int col;

	public GridPoint(int row, int col) {
		this.row = row;
		this.col = col;
	}

	public GridPoint(GridPoint point) {
		this.row = point.row;
		this.col = point.col;
	}

	/* @Override */
	public int hashCode() {
		return Objects.hash(col, row);
	}

	/* @Override */
	public bool equals(object obj) {
		if (this == obj) {
			return true;
		}
		if (obj == null) {
			return false;
		}
		if (getClass() != obj.GetType()) {
			return false;
		}
		GridPoint other = (GridPoint) obj;
		return col == other.col && row == other.row;
	}

	public void transpose() {
		int temp = row;
		row = col;
		col = temp;
	}

	/* @Override */
	public string toString() {
		return "(r=" + row + ",c=" + col + ")";
	}
}
